// Route-specific bilingual semantic overlays for festival pages whose base
// devotional guide is absent or intentionally shared. Integration is separate.

const p = (en, hi) => Object.freeze({ en, hi });
const record = (key, kind, identity, meaning, practice, completion, timingNote, sourceBoundary) => {
  const practicePair = p(...practice);
  return Object.freeze({
    key, kind, heroKey: heroKeyFor(key, kind),
    identity: p(...identity),
    meaning: p(...meaning),
    practice: practicePair,
    verdict: practicePair,
    completion: p(...completion),
    timingNote: p(...timingNote),
    sourceBoundary: p(...sourceBoundary),
  });
};

const annual = (row) => record(
  row[0], "full", [row[1], row[2]], [row[3], row[4]], [row[5], row[6]],
  [row[7] || `Complete ${row[1]} after the named worship and prasad.`, row[8] || `${row[2]} की नामित पूजा और प्रसाद के बाद अनुष्ठान पूर्ण करें।`],
  [row[9] || "Use the local tithi or temple time shown for this observance.", row[10] || "इस अनुष्ठान के लिए दिखाया स्थानीय तिथि या मंदिर-समय मानें।"],
  [row[11] || "Household and temple procedures vary; keep the received regional tradition.", row[12] || "गृह और मंदिर-विधियाँ बदलती हैं; प्राप्त क्षेत्रीय परम्परा मानें।"],
);

