FULL_ROWS.push(
  ["sakatChauth","Sakat Chauth","सकट चौथ","Magha Krishna Chaturthi honours Ganesha and Sakat Mata in a north Indian family fast distinct from monthly Sankashti.","माघ कृष्ण चतुर्थी उत्तर भारतीय कुल-व्रत में गणेश और सकट माता का सम्मान करती है और मासिक संकष्टी से अलग है।","Keep the received fast, offer til-gud and Ganesha prayer, hear the Sakat katha and use the local moonrise where the family requires it.","प्राप्त व्रत रखें, तिल-गुड़ और गणेश-प्रार्थना अर्पित करें, सकट कथा सुनें और कुल में आवश्यक हो तो स्थानीय चन्द्रोदय मानें।"],
  ["mauniAmavasya","Mauni Amavasya","मौनी अमावस्या","Magha Amavasya centres silence, inward discipline, ancestor remembrance and sacred bathing traditions.","माघ अमावस्या मौन, अन्तर्मुख अनुशासन, पितृ-स्मरण और पवित्र स्नान-परम्पराओं पर केन्द्रित है।","Keep a realistic period of silence, pray or give charity, and bathe at home unless an authorised safe pilgrimage is available.","यथार्थ अवधि का मौन रखें, प्रार्थना या दान करें और अधिकृत सुरक्षित तीर्थ उपलब्ध न हो तो घर में स्नान करें।"],
  ["gangaur","Gangaur","गणगौर","Rajasthan's Gangaur honours Gauri and Shiva through spring worship, clay images, songs and community procession.","राजस्थान की गणगौर वसन्त-पूजन, मृण्मूर्ति, गीत और सामुदायिक यात्रा से गौरी-शिव का सम्मान करती है।","Worship Gauri with the household's songs and offerings; keep fasting voluntary and do not promise a marriage outcome.","कुल के गीत और अर्पण से गौरी पूजें; व्रत स्वैच्छिक रखें और विवाह-फल का वचन न दें।"],
  ["kajariTeej","Kajari Teej","कजरी तीज","Kajari Teej is a monsoon Gauri observance known for kajari songs and regional women's gatherings.","कजरी तीज मानसून का गौरी-पर्व है, जो कजरी गीत और क्षेत्रीय स्त्री-समूहों के लिए जाना जाता है।","Offer Gauri worship, sing the local kajari tradition and follow the family's food rule without universal marital claims.","गौरी-पूजन करें, स्थानीय कजरी परम्परा गाएँ और सार्वभौमिक दाम्पत्य-फल बताए बिना कुल का आहार-नियम रखें।"],
  ["rishiPanchami","Rishi Panchami","ऋषि पंचमी","Rishi Panchami honours the sapta rishis through purification customs inherited in particular households.","ऋषि पंचमी विशिष्ट कुलों में प्राप्त शुद्धि-परम्पराओं से सप्तऋषियों का सम्मान करती है।","Worship the seven sages with water, flowers and prayer; describe menstrual restrictions as inherited religious custom, not medical impurity.","जल, पुष्प और प्रार्थना से सप्तऋषि पूजें; मासिक धर्म-वर्जन को प्राप्त धार्मिक रीति कहें, चिकित्सकीय अशुद्धि नहीं।"],
  ["vishwakarmaPuja","Vishwakarma Puja","विश्वकर्मा पूजा","The day honours Vishwakarma as divine architect and the dignity and safety of skilled work.","यह दिन विश्वकर्मा को दिव्य शिल्पी और कुशल श्रम की गरिमा तथा सुरक्षा के प्रतीक रूप में सम्मानित करता है।","Clean and respectfully place tools or machines, pause operation for prayer, and never decorate moving or energised equipment.","औजार या मशीन स्वच्छ कर आदर से रखें, पूजा में संचालन रोकें और चलती या विद्युतयुक्त मशीन न सजाएँ।"],
  ["saraswatiAvahan","Saraswati Avahan","सरस्वती आवाहन","The Avahan formally invites Saraswati at the opening of the regional autumn learning-and-Ayudha sequence.","आवाहन क्षेत्रीय शारदीय विद्या और आयुध-पूजा क्रम के आरम्भ में सरस्वती को औपचारिक निमंत्रण है।","Place books or instruments respectfully and invite Saraswati with lamp and flowers; keep them in the sequence until Puja completion.","पुस्तक या वाद्य आदर से रखकर दीप-पुष्प से सरस्वती का आवाहन करें; पूजा-समापन तक क्रम में रखें।"],
  ["saraswatiPuja","Saraswati Puja / Ayudha Puja","सरस्वती पूजा / आयुध पूजा","This regional Navratri day worships learning, instruments, tools and the work they support.","यह क्षेत्रीय नवरात्रि दिवस विद्या, वाद्य, औजार और उनसे होने वाले कर्म का पूजन करता है।","Offer flowers to books, instruments or safely de-energised tools, then resume study or work only after the local completion rite.","पुस्तक, वाद्य या सुरक्षित रूप से बन्द औजारों को पुष्प दें; स्थानीय समापन-विधि के बाद ही अध्ययन या काम पुनः आरम्भ करें।"],
  ["kojagaraPuja","Kojagara Lakshmi Puja","कोजागरा लक्ष्मी पूजा","The Sharad full-moon night asks 'who is awake?' and honours Lakshmi through wakeful, ethical household prosperity.","शरद पूर्णिमा की रात्रि 'कौन जाग रहा है?' के भाव से लक्ष्मी और धर्मपूर्ण गृह-समृद्धि का सम्मान करती है।","In the local night window offer Lakshmi a lamp, flowers and naivedya, keep a gentle vigil and avoid gambling-as-religion claims.","स्थानीय रात्रि-समय में लक्ष्मी को दीप, फूल और नैवेद्य दें, सरल जागरण रखें और जुए को धार्मिक आवश्यकता न कहें।"],
  ["vivahPanchami","Vivah Panchami","विवाह पंचमी","Vivah Panchami celebrates the marriage of Rama and Sita and the dharmic partnership remembered in the Ramayana.","विवाह पंचमी राम-सीता विवाह और रामायण में स्मरण धर्ममय दाम्पत्य का उत्सव है।","Offer Rama-Sita flowers, hear the wedding episode and sing family mangal songs without promising marriage results.","राम-सीता को पुष्प अर्पित करें, विवाह-प्रसंग सुनें और विवाह-फल का वचन दिए बिना कुल-मंगलगीत गाएँ।"],
  ["gitaJayanti","Gita Jayanti","गीता जयंती","Gita Jayanti marks Krishna's teaching to Arjuna on Mokshada Ekadashi, centring discernment and selfless action.","गीता जयंती मोक्षदा एकादशी पर अर्जुन को कृष्ण के उपदेश और विवेकपूर्ण निष्काम कर्म का स्मरण है।","Read or hear a chosen Gita chapter, reflect on one teaching and offer the study to Krishna.","चुना गीता अध्याय पढ़ें या सुनें, एक शिक्षा पर मनन करें और अध्ययन कृष्ण को अर्पित करें।"],
  ["parashuramaJayanti","Parashurama Jayanti","परशुराम जयंती","The Jayanti remembers Vishnu's Parashurama form and traditions concerning duty, power and restraint.","यह जयंती विष्णु के परशुराम स्वरूप और कर्तव्य, शक्ति तथा संयम से जुड़ी परम्पराओं का स्मरण है।","Worship Vishnu-Parashurama with lamp and prayer, read a known narrative and avoid glorifying violence.","दीप और प्रार्थना से विष्णु-परशुराम पूजें, परिचित कथा पढ़ें और हिंसा का महिमामण्डन न करें।"],
  ["sitaNavami","Sita Navami","सीता नवमी","Sita Navami honours Sita's appearance, courage, earth connection and steadfast dharma.","सीता नवमी सीता के प्राकट्य, साहस, पृथ्वी-सम्बन्ध और अडिग धर्म का सम्मान करती है।","Offer Sita-Rama flowers, hear the appearance story and pray for courage and just household conduct.","सीता-राम को पुष्प दें, प्राकट्य-कथा सुनें और साहस तथा न्यायपूर्ण गृह-आचरण की प्रार्थना करें।"],
  ["narasimhaJayanti","Narasimha Jayanti","नृसिंह जयंती","Narasimha Jayanti remembers Vishnu appearing at twilight to protect Prahlada and uphold the divine promise.","नृसिंह जयंती संध्या में विष्णु के प्राकट्य, प्रह्लाद की रक्षा और दिव्य वचन की पूर्ति का स्मरण है।","Keep Vishnu worship through the displayed sunset window, hear Prahlada's story and complete the fast by Vaishnava rule.","दिखाए सूर्यास्त-समय तक विष्णु-पूजन रखें, प्रह्लाद कथा सुनें और वैष्णव नियम से व्रत पूरा करें।"],
  ["naradaJayanti","Narada Jayanti","नारद जयंती","Narada Jayanti honours the divine sage as messenger, musician and tireless bearer of Narayana's name.","नारद जयंती देवर्षि को संदेशवाहक, संगीतज्ञ और नारायण-नाम के अथक वाहक रूप में सम्मानित करती है।","Offer Vishnu-Narada prayer, sing a familiar bhajan and dedicate careful, truthful speech.","विष्णु-नारद प्रार्थना, परिचित भजन और सावधान सत्य वाणी का संकल्प अर्पित करें।"],
  ["shaniJayanti","Shani Jayanti","शनि जयंती","Shani Jayanti honours Shani as the graha of consequence, patience, justice and disciplined service.","शनि जयंती शनि को कर्मफल, धैर्य, न्याय और अनुशासित सेवा के ग्रह रूप में सम्मानित करती है।","Offer a supervised sesame-oil lamp where accepted, pray and serve people in need; reject fear sales and guaranteed remedies.","मान्य हो तो सुरक्षित तिल-तेल दीप दें, प्रार्थना और जरूरतमन्द सेवा करें; भय-विक्रय और निश्चित उपाय अस्वीकार करें।"],
  ["balaramaJayanti","Balarama Jayanti","बलराम जयंती","Balarama Jayanti honours Krishna's elder brother, agricultural strength, protection and grounded duty.","बलराम जयंती कृष्ण के अग्रज की कृषि-शक्ति, रक्षा और धरातलीय कर्तव्य का सम्मान करती है।","Offer Balarama-Krishna flowers and seasonal food, hear the birth story and honour ethical farm labour.","बलराम-कृष्ण को पुष्प और मौसमी अन्न दें, जन्म-कथा सुनें और धर्मपूर्ण कृषि-श्रम का सम्मान करें।"],
  ["dattatreyaJayanti","Dattatreya Jayanti","दत्तात्रेय जयंती","The full-moon Jayanti honours Dattatreya as teacher and integrated form associated with Brahma, Vishnu and Shiva.","पूर्णिमा जयंती दत्तात्रेय को गुरु और ब्रह्मा-विष्णु-शिव से जुड़े समन्वित स्वरूप में सम्मानित करती है।","Offer lamp, flowers and Guru prayer, read a familiar Dattatreya account and follow lineage-specific recitation.","दीप, पुष्प और गुरु-प्रार्थना दें, परिचित दत्तात्रेय कथा पढ़ें और परम्परा-विशेष पाठ मानें।"],
  ["swaminarayanJayanti","Swaminarayan Jayanti","स्वामीनारायण जयंती","The Jayanti marks Bhagwan Swaminarayan's birth on the Ram Navami tithi within his community's devotional tradition.","यह जयंती राम नवमी तिथि पर भगवान स्वामीनारायण के जन्म को उनकी सामुदायिक भक्ति-परम्परा में स्मरण करती है।","Join the community's sabha, kirtan and temple birth celebration; do not replace it with the Rama Navami household sequence.","समुदाय की सभा, कीर्तन और मंदिर जन्मोत्सव में सम्मिलित हों; इसे राम नवमी की गृह-विधि से न बदलें।"],
  ["vinayakaChaturthi","Vinayaka Chaturthi","विनायक चतुर्थी","Monthly Shukla Chaturthi honours Ganesha as Vinayaka and is distinct from the annual Bhadrapada festival.","मासिक शुक्ल चतुर्थी विनायक रूप में गणेश का सम्मान करती है और भाद्रपद के वार्षिक पर्व से अलग है।","Offer lamp, durva where accepted and a simple Ganesha prayer; no installation or visarjan is required monthly.","दीप, मान्य हो तो दूर्वा और सरल गणेश-प्रार्थना दें; मासिक व्रत में स्थापना या विसर्जन आवश्यक नहीं।"],
  ["kalashtami","Kalashtami","कालाष्टमी","Monthly Krishna Ashtami honours Kalabhairava and is distinct from the annual Kalabhairav Jayanti.","मासिक कृष्ण अष्टमी कालभैरव का सम्मान करती है और वार्षिक कालभैरव जयंती से अलग है।","Keep evening Shiva-Bhairava prayer with lamp and family fast rule; specialised night rites remain temple-led.","संध्या में दीप सहित शिव-भैरव प्रार्थना और कुल का व्रत-नियम रखें; विशेष रात्रि-विधि मंदिर-निर्देशित रहे।"],
);

export const FESTIVAL_ROUTE_CONTENT = Object.freeze(Object.fromEntries([
  ...FULL_ROWS.map((row) => [row[0], annual(row)]),
  ...EKADASHI_ROWS.map((row) => [row[0], ekadashi(row)]),
  ...PRADOSH_ROWS.map((row) => [row[0], pradosh(row)]),
]));

export const FESTIVAL_ROUTE_CONTENT_KEYS = Object.freeze(Object.keys(FESTIVAL_ROUTE_CONTENT));

export function festivalRouteContentFor(key) {
  return FESTIVAL_ROUTE_CONTENT[key] || null;
}
